#!/usr/bin/env python3
"""Sample testcases
Use this script to ensure that your improved program is at least not completely broken.
"""
import subprocess

PROG_NAME = './prog-3'
TESTCASE = [
    {"input": "4f503120302c3132330a4f503120312c3233340a4f503320302c310a5f5f454f465f5f0a", "output": ""},
    {"input": "4f503120322c313134343639323635380a4f503120312c323735373331363235300a4f503120372c323038383234323633390a4f503120362c310a4f503120332c300a4f503120382c36353939363432380a4f503720332c382c31310a4f503420382c360a4f503520322c370a4f503320322c310a4f503920360a4f503220382c320a5f5f454f465f5f0a", "output": ""},
    {"input": "", "output": ""},
    {"input": "", "output": ""}
]

def run_test(path: str, testcase: dict[str, str]) -> bool:
    # Run test
    p = subprocess.Popen([path],
                         stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    try:
        stdout, _ = p.communicate(bytes.fromhex(testcase['input']), timeout=3)

    except subprocess.TimeoutExpired:
        # Timeout
        print("[-] Timeout")
        return False

    finally:
        p.kill()

    # Check output
    assert stdout.hex() == testcase['output'], \
        f"Test failed: \n" \
        f"  Input: {bytes.fromhex(testcase['input'])}\n" \
        f"  Expected: {bytes.fromhex(testcase['output'])}" \
        f"  Output: {stdout}"

    return True

if __name__ == '__main__':
    ok = 0
    for i, test in enumerate(TESTCASE):
        print(f"[+] Running test {i+1}/{len(TESTCASE)}")
        if run_test(PROG_NAME, test):
            ok += 1
    print(f"[+] All tests passed ({ok}/{len(TESTCASE)} are correct)")
